SELECT hd.hd_buy_potential, sm.sm_ship_mode_id, COUNT(DISTINCT c.c_customer_sk) AS unique_customers, SUM(cs.cs_ext_ship_cost) AS total_ship_cost, CASE WHEN SUM(cs.cs_ext_ship_cost) > 200000 THEN 'Expensive' ELSE 'Affordable' END AS cost_category FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY hd.hd_buy_potential, sm.sm_ship_mode_id HAVING COUNT(DISTINCT c.c_customer_sk) > 50 ORDER BY total_ship_cost ASC LIMIT 10
